const BRANCH = /^[A-Za-z0-9._/-]{1,100}$/;
const INSTANT = /^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,3})?Z$/;

function clean(raw) {
  const detail = {};
