// verifySources recomputes that summary from GitHub's base and head bytes. Only a known lockfile marked as
// summarized with exactly the fixed placeholder is exempt, so the exemption cannot carry other text.
const summarized = item => item.lockfile === true && isLockfile(item.path) && item.patch === LOCKFILE_PATCH;

// Under the protected `local_review.binding: "diff"` a receipt covers the change, not the trees: the SHA-256 of the
// normalized diff the reviewers signed must equal the SHA-256 of the normalized diff GitHub reports for the pull request.
// Normalized: per file, in path order, its path, status and (for a rename) previous path, and its hunks with every hunk
// header reduced to `@@`, so line numbers and git's trailing section text do not count. Every other hunk byte counts,
// context lines and whitespace included. GitHub joins two git hunks separated by exactly one unchanged line into one hunk
// whose context run between changes is 2 * 3 + 1 = 7 lines; git with its default 3 lines of context never emits such a run
// inside a hunk, so on both sides such a run is split back into its two hunks (the joining line is dropped).
const CONTEXT = 3;
function canonicalHunks(patch) {
  const lines = patch.split('\n');
  const out = [];
  let run = [];
  const flush = closing => {
    // A run of context lines between two change lines of one hunk; exactly 2 * CONTEXT + 1 of them is GitHub's join.
    if (closing && run.length === 2 * CONTEXT + 1 && out.length && /^[+-]/.test(out[out.length - 1])) {
      out.push(...run.slice(0, CONTEXT), '@@', ...run.slice(CONTEXT + 1));
    } else out.push(...run);
    run = [];
  };
  for (const line of lines) {
    if (line.startsWith('@@')) {flush(false); out.push('@@'); continue;}
    if (line.startsWith(' ')) {run.push(line); continue;}
    flush(/^[+-]/.test(line));
    out.push(line);
  }
  flush(false);
  return out.join('\n');
}

// The normalized entry of every changed file: a summarized lockfile is bound by its recomputed summary (verifySources), so
// it contributes its path, status and a fixed marker; a change that shows no text contributes an empty patch.
const entry = (path, status, previous, patch) => ({path, status, previous: status === 'renamed' ? previous : null, patch});
const diffDigest = entries => crypto.createHash('sha256').update(JSON.stringify(['clouseau.receipt-diff.v1',
  [...entries].sort((a, b) => a.path < b.path ? -1 : 1)])).digest('hex');

function verifyPatches({snapshot, files, binding = null}) {
  const signed = new Map(snapshot.files.map(file => [file.path, file]));
  // GitHub supplies no patch for very large or binary changes; the hosted collector refuses those and so does this.
  // It also supplies none for a change that shows no text, which the signed sources prove: an empty file added or
  // removed, or a rename of identical content. Then the signed patch must be a header with no hunk.
  const textless = live => {
    const item = signed.get(live.filename);
    const text = id => snapshot.sources?.[id]?.content;
    return Boolean(item) && item.status === live.status && hostedForm(signedPatch(snapshot, item), live) === '' &&
      showsNoText(item.status, text(item.base_source), text(item.head_source));
  };
  // Under binding "diff" the live sources are never read, so nothing at the live head proves that a file without a patch
  // still shows no text: an empty file that later gains binary or oversized content would also arrive without one.
  if (files.some(file => (typeof file.patch !== 'string' || !file.patch) &&
    !(signed.has(file.filename) && summarized(signed.get(file.filename))) && !(binding !== 'diff' && textless(file)))) {
    throw new Error('Changed-file evidence is incomplete');
  }
  for (const file of snapshot.files) if (!files.some(live => live.filename === file.path)) throw new ReceiptPatchMismatch(file.path);
  for (const live of files) {
    const item = signed.get(live.filename);
    if (item && item.lockfile === true && !summarized(item)) throw new ReceiptPatchMismatch(live.filename);
    if (item && summarized(item)) {
      if (item.status !== live.status) throw new ReceiptPatchMismatch(live.filename);
      continue;
    }
    if (!item || item.status !== live.status) throw new ReceiptPatchMismatch(live.filename);
    if (binding === 'diff') {
      if (canonicalHunks(hostedForm(signedPatch(snapshot, item), live) ?? '\0') !== canonicalHunks(live.patch)) throw new ReceiptPatchMismatch(live.filename);
      continue;
    }
    const signedText = withoutHeading(hostedForm(signedPatch(snapshot, item), live) ?? '');
    const hostedText = withoutHeading(live.patch ?? '');
    if (signedText !== hostedText && !joinsSingleGaps(signedText, hostedText)) throw new ReceiptPatchMismatch(live.filename);
  }
  if (binding !== 'diff') return null;
  // Every live file here has a patch: a patchless one was refused above unless it is a summarized lockfile.
  // The binding itself: one SHA-256 over the signed patches and one over GitHub's, which the per-file comparison above proved equal.
  const previousOf = item => snapshot.sources?.[item.base_source]?.path ?? null;
  const signedDigest = diffDigest(snapshot.files.map(item => summarized(item) ? entry(item.path, item.status, null, 'lockfile-summary') :
    entry(item.path, item.status, previousOf(item), canonicalHunks(hostedForm(signedPatch(snapshot, item),
      {filename: item.path, status: item.status, previous_filename: item.status === 'renamed' ? previousOf(item) : undefined}) ?? '\0'))));
  const liveDigest = diffDigest(files.map(live => summarized(signed.get(live.filename)) ? entry(live.filename, live.status, null, 'lockfile-summary') :
    entry(live.filename, live.status, live.previous_filename ?? null, canonicalHunks(live.patch))));
  if (signedDigest !== liveDigest) throw new ReceiptPatchMismatch(snapshot.files[0].path);
  return {signed: signedDigest, live: liveDigest};
}

// Under the protected `local_review.binding: "diff"` a compatibility declaration (`compat/declarations/<sha256>.json`, see
// docs/receipt-compatibility.md) is not part of the diff a receipt covers. Declarations pin the full content of the semantic
// files they cover, so a merge of the base into a pull request that shares a semantic file with an earlier merged one forces a
// re-declaration that changes nothing the review judged. What a declaration means to a review is its verdict and the files it
// covers; those must stay equal. The signed declarations and the pull request's must carry the same verdicts over the same
// files (path, mode, and whether the file is deleted); only the content digests they pin may differ, and the required
// `verify` job still checks every declaration against the merged tree (docs/receipt-compatibility.md). Only a file added under
// exactly that name with a well-formed declaration as its whole content counts; anything else under the directory is an
// ordinary changed file and is compared byte for byte like every other.
const DECLARATION = /^compat\/declarations\/[a-f0-9]{64}\.json$/;
function declarationMeaning(path, status, patch) {
  if (!DECLARATION.test(path) || status !== 'added' || typeof patch !== 'string') return null;
  const [header, ...body] = patch.split('\n');
  if (!/^@@ -0,0 \+1(?:,\d+)? @@$/.test(header) || !body.length || !body.every(line => line.startsWith('+'))) return null;
  let value;
  try {value = JSON.parse(body.map(line => line.slice(1)).join('\n'));} catch {return null;}
  const hash = text => typeof text === 'string' && /^[a-f0-9]{64}$/.test(text);
  if (!value || value.version !== 1 || !['compatible', 'incompatible'].includes(value.decision) || !Array.isArray(value.changes) ||
    !value.changes.length || !value.changes.every(change => change && typeof change.path === 'string' && Number.isInteger(change.mode) &&
      (hash(change.sha256) || change.sha256 === null))) return null;
  return JSON.stringify([value.decision, value.changes.map(change => [change.path, change.mode, change.sha256 === null])]);
}

// The one rule both the receipt binding (withoutDeclarations) and the owner's diff-following confirmation (policy.cjs
// confirms) apply: split changed files into declarations, compared by their meaning, and every other file, compared byte for
// byte. `entries` are {path, status, patch}; the result keeps the other entries in order and the meanings sorted.
function splitDeclarations(entries) {
  const meanings = []; const others = [];
  for (const entry of entries) {
    const meaning = declarationMeaning(entry.path, entry.status, entry.patch);
    if (meaning === null) others.push(entry); else meanings.push(meaning);
  }
  return {meanings: meanings.sort(), others};
}

function withoutDeclarations({snapshot, files}) {
  const signedSplit = splitDeclarations(snapshot.files.map(item => ({item, path: item.path, status: item.status,
    patch: hostedForm(signedPatch(snapshot, item), {filename: item.path, status: item.status})})));
  const liveSplit = splitDeclarations(files.map(file => ({file, path: file.filename, status: file.status, patch: file.patch})));
  const signed = snapshot.files.filter(item => !signedSplit.others.some(entry => entry.item === item));
  const live = files.filter(file => !liveSplit.others.some(entry => entry.file === file));
  if (JSON.stringify(signedSplit.meanings) !== JSON.stringify(liveSplit.meanings)) {
    throw new ReceiptPatchMismatch((signed[0] ?? live[0]).path ?? (signed[0] ?? live[0]).filename);
  }
  const dropped = new Set(signed.map(item => item.path));
  return {snapshot: {...snapshot, files: snapshot.files.filter(item => !dropped.has(item.path)), paths: snapshot.paths.filter(path => !dropped.has(path))},
    files: files.filter(file => !live.includes(file))};
}

module.exports = {ReceiptPatchMismatch, hostedForm, verifyPatches, canonicalHunks, diffDigest, withoutDeclarations, splitDeclarations};

'use strict';
const {test} = require('node:test');
const assert = require('node:assert/strict');
const cp = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {githubReader, RECEIPT_RESPONSE_LIMIT} = require('./receipt-standing.cjs');
const {MAX_RECEIPT_BYTES} = require('./local-receipt.cjs');

// A `gh` on PATH that prints a git blob response whose base64 content has `size` bytes, wrapped every 60 characters as GitHub does.
function fakeGh(t, size) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-fake-gh-'));
  t.after(() => fs.rmSync(directory, {recursive: true, force: true}));
  const content = Buffer.alloc(size, 7).toString('base64').replace(/(.{60})/g, '$1\n');
  fs.writeFileSync(path.join(directory, 'blob.json'), JSON.stringify({sha: 'b'.repeat(40), size, encoding: 'base64', content}));
  fs.writeFileSync(path.join(directory, 'gh'), `#!/bin/sh\nexec cat "${directory}/blob.json"\n`, {mode: 0o755});
  const previous = process.env.PATH;
  process.env.PATH = `${directory}${path.delimiter}${previous}`;
  t.after(() => {process.env.PATH = previous;});
}

const blob = reader => reader.rest.git.getBlob({owner: 'o', repo: 'r', file_sha: 'b'.repeat(40)});

test('the read limit covers the largest receipt blob GitHub can return, base64 and line wrapping included', () => {
  const wrapped = Math.ceil(MAX_RECEIPT_BYTES / 3) * 4 + Math.ceil(Math.ceil(MAX_RECEIPT_BYTES / 3) * 4 / 60) * 2;
  assert.ok(RECEIPT_RESPONSE_LIMIT > wrapped && RECEIPT_RESPONSE_LIMIT > 1024 * 1024);
});

test('a receipt blob larger than the default 1 MiB gh output buffer is read through the real gh process', async t => {
  fakeGh(t, 1200000);
  const {data} = await blob(githubReader(cp.execFileSync));
  assert.equal(Buffer.from(data.content, 'base64').length, 1200000);
});

test('a receipt blob at the receipt size cap is read in full', async t => {
  fakeGh(t, MAX_RECEIPT_BYTES);
  const {data} = await blob(githubReader(cp.execFileSync));
  assert.equal(Buffer.from(data.content, 'base64').length, MAX_RECEIPT_BYTES);
});

test('a response over the limit fails naming the limit, without a fallback or a status', async t => {
  fakeGh(t, MAX_RECEIPT_BYTES + 200000);
  await assert.rejects(blob(githubReader(cp.execFileSync)), error => error.status === undefined &&
    error.message.includes(`${RECEIPT_RESPONSE_LIMIT}-byte`) && error.message.includes(`${MAX_RECEIPT_BYTES}-byte receipt size cap`) &&
    !/spawnSync gh ENOBUFS/.test(error.message));
});

'use strict';
// A signed local receipt may attest the repository's whole declared verification.
//
// Local side: `evaluate` runs after the recipe's commands and refuses (throws) unless EVERY declared command ran and passed on the exact
// head, native coverage was observed in this run, and the coverage gate CI would enforce (exact, changed_lines or declared) passes.
// Only then does the signed verification record carry `attestation`. A review that cannot attest is never signed.
//
// CI side: `receiptAttests` answers whether the pull request's receipt is fully valid (signature, head, base, engine, expiry, sources)
// AND carries that attestation. Any other answer is false and the repository's own verification runs exactly as before.
const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const temporaryDirectories = require('./temp-dirs.cjs');

const VERSION = 1;
const GATE_MODES = ['exact', 'changed_lines', 'declared'];

const describe = command => {
  const text = command.argv.join(' ');
  const shown = text.length > 120 ? `${text.slice(0, 117)}...` : text;
  if (command.error) return `${shown} could not run (${command.error.code || command.error.message}); install the tool it needs`;
  if (command.signal) return `${shown} was stopped by ${command.signal}`;
  if (command.exit_code === null) return `${shown} did not exit`;
  return `${shown} exited ${command.exit_code}`;
};

// The attestation of a verification record, or null. A record attests only when it says so AND its own facts agree.
function attestationOf(technical) {
  const claim = technical?.attestation;
  const ok = claim && claim.version === VERSION && GATE_MODES.includes(claim.coverage_mode) && claim.gate === 'passed' &&
    Array.isArray(technical.commands) && technical.commands.length > 0 && claim.commands === technical.commands.length &&
    technical.verification_status === 'passed' && technical.commands.every(command => command.exit_code === 0 && !command.error && !command.signal) &&
    technical.coverage?.status !== 'unavailable' && technical.coverage?.artifact_freshness === 'observed_current_run' &&
    typeof technical.local_config_digest === 'string' && claim.recipe === technical.local_config_digest;
  return ok ? claim : null;
}

// Baseline totals of the base revision, measured the way the CI job measures them: the same recipe on a clean checkout of the base.
// The checkout lives under the work directory, not the system temp directory, so a recipe step that bind-mounts it into a
// container (Docker Compose under Colima, which shares only the home directory by default) sees the files.
function withBaseline({directory, baseSha, config, parts, verify, exec, gate, work}, use) {
  const temporary = temporaryDirectories.create('clouseau-base-', work);
  const tree = path.join(temporary, 'tree');
  try {
    exec('git', ['-C', directory, 'worktree', 'add', '--detach', tree, baseSha], {stdio: 'pipe'});
    const result = verify({directory: tree, config});
    if (result.verification_status !== 'passed') {
      throw new Error(`the base revision's own verification failed (${result.commands.filter(item => item.exit_code !== 0 || item.error).map(describe).join('; ')}), so no coverage baseline exists`);
    }
    const file = path.join(temporary, 'baseline.json');
    fs.writeFileSync(file, JSON.stringify(gate.measurePlan(parts, tree).totals));
    return use(file);
  } finally {
    try {exec('git', ['-C', directory, 'worktree', 'remove', '--force', tree], {stdio: 'pipe'});} catch { /* the temporary directory is removed next */ }
    temporaryDirectories.dispose(temporary);
  }
}

// Returns `technical` with its attestation, or throws naming exactly why a signature must not be issued.
function evaluate({directory, config, technical, ciConfig, baseSha, verify, exec = cp.execFileSync, work = temporaryDirectories.workDirectory()}) {
  const refuse = problems => {throw new Error(`Local verification is not complete on this head, so no receipt is signed: ${problems.join('; ')}`);};
  const failed = technical.commands.filter(command => command.exit_code !== 0 || command.error || command.signal);
  if (failed.length) refuse(failed.map(describe));
  if (technical.coverage.status === 'unavailable') refuse([`native coverage is unavailable (${technical.coverage.error || 'no report'}); install the coverage tool the recipe needs`]);
  if (technical.coverage.artifact_freshness !== 'observed_current_run') refuse(['the coverage report was not produced by this run']);
  const gate = require('./coverage-gate.cjs');
  const changed = require('./coverage-changed.cjs');
  const mode = changed.modeOf(ciConfig);
  try {
    if (mode === 'exact') {
      if (!technical.coverage.passed) throw new Error('line and branch coverage is not exactly 100%');
    } else {
      const parts = require('./coverage-plan.cjs').coverageParts(config);
      if (mode === 'declared') gate.declaredPlan(parts, directory, baseSha);
      else withBaseline({directory, baseSha, config, parts, verify, exec, gate, work}, file => gate.changedPlan(parts, directory, baseSha, file));
    }
  } catch (error) {
    refuse([`the ${mode} coverage gate fails: ${error.message}`]);
  }
  return {...technical, attestation: {version: VERSION, recipe: technical.local_config_digest, commands: technical.commands.length,
    coverage_mode: mode, gate: 'passed'}};
}

// CI: does this pull request carry a receipt that is valid in every respect and attests verification? Never throws on a
// receipt that does not verify; that is simply `false` (the repository then runs its checks itself). With `explain`, the
// answer is `{attests, rejected, detail}`: `rejected` is the fixed receipt class (receipt-rejection.cjs) when a claimed
// receipt was refused, else null, and `detail` holds only the values that class may show. The decision is the same.
async function receiptAttests(options) {
  const verdict = await attestationVerdict(options);
  return options.explain ? verdict : verdict.attests;
}

async function attestationVerdict({github, repo, pr, config, engine}) {
  const no = (rejected = null, detail = {}) => ({attests: false, rejected, detail});
  if (!config.local_review) return no();
  const receipts = require('./local-receipt.cjs');
  const {digest} = require('./acceptance.cjs');
  const {policyDigest} = require('./acceptance-controller.cjs');
  const screened = await receipts.screenReceipt({github, repo, pr, engine, trust: config.local_review, configDigest: digest(config), policyDigest: policyDigest()});
  if (!screened.ref) return no(screened.rejected ?? null, screened.detail ?? {});
  const files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number: pr.number, per_page: 100});
  const rejected = await receipts.screenSources({github, repo, pr, snapshot: screened.verified.record.snapshot, config, files,
    reviewerSha: screened.bundle.payload.reviewer_sha});
  if (rejected) return no(rejected);
  const {sources} = screened.verified.record.snapshot;
  // The attested recipe must be the accepted base's own `.clouseau-local.json`, which screenSources bound to the base revision.
  // Under the protected `binding: "diff"` the receipt names its own base, so its recipe must also equal the live base's recipe:
  // a base move that changed the declared verification never lets CI skip the new one.
  const diff = config.local_review.binding === 'diff';
  const base = diff ? screened.verified.record.snapshot.base_sha : pr.base.sha;
  const recipe = Object.values(sources).find(item => item.path === '.clouseau-local.json' && item.ref === base);
  let technical = null;
  let accepted = null;
  try {
    technical = JSON.parse(sources.verification.content);
    accepted = digest(JSON.parse(recipe.content));
    if (diff) {
      const {data} = await github.rest.repos.getContent({...repo, path: '.clouseau-local.json', ref: pr.base.sha});
      if (digest(JSON.parse(Buffer.from(data.content, 'base64').toString('utf8'))) !== accepted) return no();
    }
  } catch { return no(); }
  return {attests: attestationOf(technical) !== null && technical.local_config_digest === accepted, rejected: null, detail: {}};
}

// The decision the `attested` action operation publishes for a workflow's `if:` conditions.
async function decide({github, context, config, engine}) {
  const number = context.payload.pull_request?.number;
  if (!Number.isInteger(number)) throw new Error('A pull request context is required');
  const {data: pr} = await require('./pull-read.cjs').readPull(github, context.repo, number);
  if (pr.state !== 'open' || pr.draft || pr.base.ref !== config.base_branch) return false;
  return receiptAttests({github, repo: context.repo, pr, config, engine});
}

// The packaged step's decision. Any failure leaves the checks to run (the step continues on error), but never quietly: the
// job summary and a warning say the receipt was not consulted and why, so the full run is not mistaken for a normal one.
async function decideVisibly({github, context, config, engine, core}) {
  try {
    const attested = await decide({github, context, config, engine});
    core.setOutput('attested', String(attested));
    core.info(attested ? 'A valid local receipt attests the verification; its checks may be skipped.' : 'No valid receipt attests the verification; run the checks.');
    return attested;
  } catch (error) {
    const why = require('./transient-retry.cjs').isTransient(error) ? 'GitHub API unavailable' :
      `the decision failed (${Number.isInteger(error?.status) ? `HTTP ${error.status}` : 'no HTTP status'})`;
    const line = `Receipt not consulted: ${why}; verification ran in full.`;
    core.setOutput('attested', 'false');
    core.warning(line);
    await core.summary.addRaw(`## Clouseau: receipt not consulted\n\n${line}\n`).write();
    throw error;
  }
}

module.exports = {VERSION, GATE_MODES, attestationOf, evaluate, receiptAttests, decide, decideVisibly};

